-- palashroy.me content database schema + seed
-- Import this in phpMyAdmin (into your new database).

CREATE TABLE IF NOT EXISTS `content` (
  `section` VARCHAR(50) NOT NULL PRIMARY KEY,
  `data` LONGTEXT NOT NULL,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `failed_attempts` INT NOT NULL DEFAULT 0,
  `locked_until` INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Seed content
INSERT INTO `content` (`section`,`data`) VALUES ('publications', '[{"title": "A Unified Model for Cross-Domain Clone Detection via Model Merging", "authors": "P. R. Roy, B. Roy, K. A. Schneider and C. K. Roy", "venue": "41st IEEE/ACM International Conference on Automated Software Engineering (ASE)", "year": "2026", "pages": "pp. 1496-1508", "description": "Studies post-hoc model merging (task-vector methods such as TIES, DARE-TIES, WUDI and PCB, plus layer stitching) as a way to combine domain-specialist clone detectors into one cross-domain detector without access to training data at merge time.", "doi": "10.1145/3832783.3837415", "bibtex": "@inproceedings{roy2026crossdomain,\\n  series = {ASE ''26},\\n  title = {A Unified Model for Cross-Domain Clone Detection via Model Merging},\\n  url = {https://doi.org/10.1145/3832783.3837415},\\n  doi = {10.1145/3832783.3837415},\\n  booktitle = {Proceedings of the 41st IEEE/ACM International Conference on Automated Software Engineering},\\n  publisher = {ACM},\\n  author = {Roy, Palash R. and Roy, Banani and Schneider, Kevin A. and Roy, Chanchal K.},\\n  year = {2026},\\n  month = {Oct},\\n  pages = {1496--1508}\\n}", "slug": "cross-domain-clone-detection-model-merging", "type": "conference", "authors_full": ["Palash Ranjan Roy", "Banani Roy", "Kevin A. Schneider", "Chanchal K. Roy"], "venue_short": "ASE 2026", "venue_full": "Proceedings of the 41st IEEE/ACM International Conference on Automated Software Engineering", "publisher": "ACM", "published_date": "2026-10-07", "first_page": "1496", "last_page": "1508", "abstract": "The growing diversity of code clone types, from syntactic copies to cross-language semantic clones to AI-generated duplicates, has created a fragmentation crisis in clone detection. Current deep learning detectors are domain specialists that degrade significantly outside their training distribution. In our evaluation, F1 drops exceed 70% across domains. Deploying multiple specialized models is impractical, yet training a single cross-domain detector requires simultaneous access to all training data. To address this, we investigate model merging, a family of post-hoc techniques that operate solely on trained checkpoints. We systematically evaluate parameter merging with five task-vector methods (Task Arithmetic, TIES, DARE-TIES, WUDI, PCB), architecture merging via greedy layer stitching, and cross-tokenizer alignment. Our study spans four pre-trained code models, three benchmarks, and twelve merging configurations. Same-base TIES merging creates effective cross-domain detectors, validated across two model families and three random seeds. It reaches 0.865 combined F1 on UniXcoder, 93% of multi-task training performance without any training data at the merging step. WUDI achieves the highest in-distribution combined F1 at 0.899, but TIES generalizes better to unseen AI-generated clones. We therefore recommend TIES for the practical recipe. Cross-base merging yields only marginal and high-variance gains across all five methods. This indicates that task vector compatibility through a shared pre-trained base is the binding factor for effective merging in our setting. Merged encoder-based detectors also outperform zero-shot instruction-tuned code LLMs on GPTCloneBench (0.609 vs. 0.454 F1 for the strongest LLM baseline) at substantially lower per-pair inference cost. They also generalize up to 4× better than multi-task training to unseen AI-generated clones, suggesting a trade-off between in-domain performance and OOD robustness. This work provides one of the first systematic empirical studies of model merging for software engineering and a practical recipe for building cross-domain code clone detectors.", "problem": "Deep-learning clone detectors trained on one clone domain degrade sharply outside their training distribution, and training a single cross-domain detector requires simultaneous access to all training data.", "relevant_to": ["cross-domain code clone detection", "cross-language clone detection", "model merging", "task arithmetic and TIES merging", "out-of-distribution generalization of code models", "detection of AI-generated code clones", "pre-trained code models (UniXcoder, CodeBERT family)", "multi-task learning vs. post-hoc merging", "LLM baselines for clone detection"], "keywords": ["code clone detection", "model merging", "task vectors", "TIES", "DARE-TIES", "domain generalization", "pre-trained code models", "UniXcoder", "GPTCloneBench"], "arxiv": "2608.04215", "artifact_url": "https://doi.org/10.5281/zenodo.19187685", "selected": true, "tags": ["Software Maintenance & Evolution", "Program Comprehension", "Code Clones", "AI4SE", "Model Merging", "OOD Generalization", "Empirical SE"], "ml_topics": ["Model Merging", "Task Arithmetic (TIES, DARE)", "Out-of-Distribution Generalization", "Multi-Task Learning", "Code Language Models"]}, {"title": "MergeSE: Post-Hoc Model Merging for Software Engineering Tasks without Retraining", "authors": "P. R. Roy, B. Roy, K. A. Schneider and C. K. Roy", "venue": "41st IEEE/ACM International Conference on Automated Software Engineering (ASE), Tool Track", "year": "2026", "pages": "pp. 3532-3536", "description": "Presents MergeSE, an open-source CLI and web tool for training-free merging of HuggingFace encoder checkpoints for software engineering classification tasks, with inspect, merge, evaluate and export operations.", "doi": "10.1145/3832783.3834630", "bibtex": "@inproceedings{roy2026mergese,\\n  series = {ASE ''26},\\n  title = {MergeSE: Post-Hoc Model Merging for Software Engineering Tasks without Retraining},\\n  url = {https://doi.org/10.1145/3832783.3834630},\\n  doi = {10.1145/3832783.3834630},\\n  booktitle = {Proceedings of the 41st IEEE/ACM International Conference on Automated Software Engineering},\\n  publisher = {ACM},\\n  author = {Roy, Palash R. and Roy, Banani and Schneider, Kevin A. and Roy, Chanchal K.},\\n  year = {2026},\\n  month = {Oct},\\n  pages = {3532--3536}\\n}", "slug": "mergese", "type": "conference", "track": "Tool Track", "authors_full": ["Palash Ranjan Roy", "Banani Roy", "Kevin A. Schneider", "Chanchal K. Roy"], "venue_short": "ASE 2026 Tool Track", "venue_full": "Proceedings of the 41st IEEE/ACM International Conference on Automated Software Engineering", "publisher": "ACM", "published_date": "2026-10-07", "first_page": "3532", "last_page": "3536", "abstract": "Fine-tuned code models often behave as domain specialists and can degrade sharply under distribution shift: in our clone-detection setting, a model trained on same-language clones drops 71% F1 on cross-language clones, while multi-task training falls to 0.151 F1 on unseen AI-generated clones. Our companion study shows that post-hoc model merging can address this fragmentation, achieving 93% of multi-task performance without training data while generalizing 4× better to unseen clone types. However, no practical tool exists that lets SE researchers diagnose checkpoint compatibility, merge specialists, validate results on SE benchmarks, and export models for deployment. We present MergeSE, an open-source CLI and web tool for training-free model merging of HuggingFace encoder checkpoints. While motivated by OOD generalization in clone detection, MergeSE supports SE classification workflows more broadly through a built-in registry of nine task types, including vulnerability detection, defect prediction, and code-smell detection. MergeSE provides five operations: tasks, inspect, merge, evaluate, and export. It supports five merging algorithms, including TIES, DARE-TIES, Wudi, PCB, and averaging; detects cross-task classification-head mismatches; produces seedable deterministic outputs; and includes bundled benchmark samples for smoke-test reproduction. A full merge of two 124M-parameter checkpoints completes in under 5 seconds on CPU. End-to-end validation confirms that MergeSE-produced checkpoints match reference implementations and recover cross-domain performance from domain-specific specialists. The tool is available online at https://mergese.usask.ca, and the development repository is at https://github.com/srlabUsask/MergeSE.", "problem": "No practical tool lets software engineering researchers diagnose checkpoint compatibility, merge fine-tuned specialist models, validate them on SE benchmarks, and export them without retraining.", "relevant_to": ["model merging tools", "training-free model merging", "out-of-distribution generalization of code models", "code clone detection", "vulnerability detection", "defect prediction", "code smell detection", "HuggingFace encoder checkpoints", "reproducible SE research tooling"], "keywords": ["model merging", "TIES", "DARE-TIES", "PCB", "task vectors", "code models", "clone detection", "distribution shift", "research tool"], "arxiv": "2608.04181", "code_url": "https://github.com/srlabUsask/MergeSE", "tool_url": "https://mergese.usask.ca", "artifact_url": "https://doi.org/10.5281/zenodo.21797312", "selected": true, "tags": ["AI4SE", "SE4AI", "Model Merging", "OOD Generalization", "Tool"], "ml_topics": ["Model Merging", "Task Arithmetic (TIES, DARE)", "Multi-Task Learning", "Out-of-Distribution Generalization", "Hugging Face Tooling"]}, {"title": "Carbon-Taxed Transformers: A Green Compression Pipeline for Overgrown Language Models", "authors": "A. I. Alam, P. R. Roy, C. K. Roy, B. Roy and K. A. Schneider", "venue": "Proceedings of the ACM on Software Engineering (PACMSE), FSE 2026", "year": "2026", "pages": "pp. 1035-1058", "award": "ACM SIGSOFT Distinguished Paper Award", "description": "Winner of the ACM SIGSOFT Distinguished Paper Award. Introduces Carbon-Taxed Transformers (CTT), a green compression pipeline inspired by carbon-taxation economics that achieves up to 49x memory reduction and up to 81% lower CO2 emissions while retaining roughly 98% clone-detection accuracy across multiple transformer architectures.", "doi": "10.1145/3797075", "preprint": "/papers/CTT.pdf", "pdf": "/papers/CTT.pdf", "bibtex": "@article{alam2026ctt,\\n  title = {Carbon-Taxed Transformers: A Green Compression Pipeline for Overgrown Language Models},\\n  volume = {3},\\n  ISSN = {2994-970X},\\n  url = {https://doi.org/10.1145/3797075},\\n  doi = {10.1145/3797075},\\n  number = {FSE},\\n  journal = {Proceedings of the ACM on Software Engineering},\\n  publisher = {Association for Computing Machinery (ACM)},\\n  author = {Alam, Ajmain Inqiad and Roy, Palash and Roy, Chanchal K. and Roy, Banani and Schneider, Kevin A.},\\n  year = {2026},\\n  month = {June},\\n  pages = {1035--1058}\\n}", "slug": "carbon-taxed-transformers", "type": "journal", "authors_full": ["Ajmain Inqiad Alam", "Palash Ranjan Roy", "Chanchal K. Roy", "Banani Roy", "Kevin A. Schneider"], "venue_short": "FSE 2026 (PACMSE)", "venue_full": "Proceedings of the ACM on Software Engineering", "publisher": "Association for Computing Machinery (ACM)", "published_date": "2026-06-30", "volume": "3", "issue": "FSE", "first_page": "1035", "last_page": "1058", "issn": "2994-970X", "abstract": "The accelerating adoption of Large Language Models (LLMs) in software engineering (SE) has brought with it a silent crisis: unsustainable computational cost. While these models demonstrate remarkable capabilities in different SE tasks, they are unmanageably large, slow to deploy, memory-intensive, and carbon-heavy. This reality threatens not only the scalability and accessibility of AI-powered SE, but also its long-term environmental sustainability. The research challenge is clear: we must go beyond accuracy and address efficiency and environmental cost as first-class design constraints. To meet this challenge, we introduce Carbon-Taxed Transformers (CTT), a systematic multi-architectural compression principled pipeline ordering inspired by economic carbon taxation principles. Drawing from the economic concept of carbon pricing, CTT operationalizes a computational carbon tax that penalizes architectural inefficiencies and rewards deployment-ready compression. We evaluate CTT across three core SE tasks: code clone detection, code summarization, and code generation, with models spanning encoder-only, encoder-decoder, and decoder-only architecture. Our results show that CTT delivers on inference: (1) up to 49× memory reduction, (2) time reduction up to 8-10× for clone detection, up to 3× for summarization, and 4–7× for generation, (3) up to 81% reduction in CO2 emissions and (4) CTT retains around 98% accuracy on clone detection, around 89% on summarization, and up to 91% (textual metrics) and 68% (pass@1) for generation. Two ablation studies show that pipeline ordering and individual component contributions are both essential, providing empirical justification for CTT’s design and effectiveness. This work establishes a viable path toward responsible AI in SE through aggressive yet performance-preserving compression.", "problem": "Large language models used for software engineering tasks are large, slow, memory-intensive and carbon-heavy, so efficiency and environmental cost need to be treated as first-class design constraints alongside accuracy.", "relevant_to": ["compression of large language models for code", "green and sustainable AI for software engineering", "carbon-emission reduction of model inference", "neural architecture search, pruning, quantization and knowledge distillation", "code clone detection", "code summarization", "code generation", "efficient inference for encoder-only, encoder-decoder and decoder-only models"], "keywords": ["model compression", "green computing", "energy-efficient inference", "carbon tax", "knowledge distillation", "quantization", "pruning", "neural architecture search", "code clone detection", "code summarization", "code generation"], "arxiv": "2604.25903", "code_url": "https://github.com/srlabUsask/CTT", "selected": true, "tags": ["AI4SE", "SE4AI", "Green & Sustainable SE", "Code Clones"], "ml_topics": ["Model Compression", "Pruning", "Quantization", "Knowledge Distillation", "Efficient & Green LLMs", "Code Language Models"]}, {"title": "Carbon-Taxed Transformers: Efficient, Accurate, and Sustainable LLMs", "authors": "A. I. Alam, P. R. Roy, C. K. Roy, B. Roy and K. A. Schneider", "venue": "34th ACM International Conference on the Foundations of Software Engineering (FSE), Poster Track", "year": "2026", "pages": "pp. 1408-1409", "description": "A poster summarizing Carbon-Taxed Transformers (CTT), a pipeline for efficient, accurate, and sustainable large language models applied to software engineering tasks.", "doi": "10.1145/3803437.3807387", "preprint": "/papers/CTT_poster.pdf", "pdf": "/papers/CTT_poster.pdf", "bibtex": "@inproceedings{10.1145/3803437.3807387,\\nauthor = {Alam, Ajmain Inqiad and Roy, Palash and Roy, Chanchal and Roy, Banani and Schneider, Kevin},\\ntitle = {Carbon-Taxed Transformers: Efficient, Accurate, and Sustainable LLMs},\\nyear = {2026},\\nisbn = {9798400726361},\\npublisher = {Association for Computing Machinery},\\naddress = {New York, NY, USA},\\nurl = {https://doi.org/10.1145/3803437.3807387},\\ndoi = {10.1145/3803437.3807387},\\nabstract = {The growing adoption of Large Language Models in software engineering has introduced unsustainable computational and environmental costs. We propose Carbon-Taxed Transformers (CTT), a compression pipeline inspired by economic carbon taxation, integrating Neural Architecture Search, structured pruning, quantization, and knowledge distillation in a principled sequence. CTT generalizes across encoder-only, encoder-decoder, and decoder-only architectures, and is evaluated on code clone detection, summarization, and generation. Results show up to 49\\\\texttimes{} memory reduction, 10\\\\texttimes{} speedup, and an 81\\\\% reduction in CO2 emissions, while retaining 98\\\\% accuracy in clone detection, 89\\\\% in summarization, and up to 91\\\\% in generation. Ablation studies confirm both the pipeline ordering and each component are essential.},\\nbooktitle = {Proceedings of the 34th ACM International Conference on the Foundations of Software Engineering},\\npages = {1408--1409},\\nnumpages = {2},\\nkeywords = {model compression, green computing, energy-efficient inference},\\nlocation = {Concordia University, Montreal, QC, Canada},\\nseries = {FSE Companion ''26}\\n}", "slug": "carbon-taxed-transformers-poster", "type": "poster", "authors_full": ["Ajmain Inqiad Alam", "Palash Ranjan Roy", "Chanchal K. Roy", "Banani Roy", "Kevin A. Schneider"], "venue_short": "FSE 2026 Companion (Poster)", "venue_full": "Proceedings of the 34th ACM International Conference on the Foundations of Software Engineering", "publisher": "ACM", "published_date": "2026-07-05", "first_page": "1408", "last_page": "1409", "abstract": "The growing adoption of Large Language Models in software engineering has introduced unsustainable computational and environmental costs. We propose Carbon-Taxed Transformers (CTT), a compression pipeline inspired by economic carbon taxation, integrating Neural Architecture Search, structured pruning, quantization, and knowledge distillation in a principled sequence. CTT generalizes across encoder-only, encoder-decoder, and decoder-only architectures, and is evaluated on code clone detection, summarization, and generation. Results show up to 49× memory reduction, 10× speedup, and an 81% reduction in CO2 emissions, while retaining 98% accuracy in clone detection, 89% in summarization, and up to 91% in generation. Ablation studies confirm both the pipeline ordering and each component are essential.", "problem": "The growing use of large language models in software engineering carries unsustainable computational and environmental costs.", "relevant_to": ["compression of large language models for code", "green and sustainable AI for software engineering", "carbon-emission reduction of model inference", "neural architecture search, pruning, quantization and knowledge distillation", "code clone detection", "code summarization", "code generation"], "keywords": ["model compression", "green computing", "energy-efficient inference", "carbon tax"], "code_url": "https://github.com/srlabUsask/CTT", "companion_of": "carbon-taxed-transformers", "tags": ["AI4SE", "SE4AI", "Green & Sustainable SE", "Code Clones"], "ml_topics": ["Model Compression", "Pruning", "Quantization", "Knowledge Distillation", "Efficient & Green LLMs", "Code Language Models"]}, {"title": "Are Classical Clone Detectors Good Enough for the AI Era?", "authors": "A. I. Alam, P. R. Roy, F. Al-Omari, C. K. Roy, B. Roy and K. A. Schneider", "venue": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "year": "2025", "pages": "pp. 295-307", "description": "Evaluates the effectiveness of classical clone detection tools in the modern AI era, analyzing their performance against AI-generated code and proposing improvements for contemporary software development.", "doi": "10.1109/ICSME64153.2025.00035", "preprint": "https://arxiv.org/pdf/2509.25754", "bibtex": "@inproceedings{alam2025classical,\\n  title = {Are Classical Clone Detectors Good Enough for the AI Era?},\\n  url = {https://doi.org/10.1109/ICSME64153.2025.00035},\\n  doi = {10.1109/ICSME64153.2025.00035},\\n  booktitle = {2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)},\\n  publisher = {IEEE},\\n  author = {Alam, Ajmain I. and Roy, Palash R. and Al-omari, Farouq and Roy, Chanchal K. and Roy, Banani and Schneider, Kevin A.},\\n  year = {2025},\\n  month = {Sept},\\n  pages = {295--307}\\n}", "slug": "classical-clone-detectors-ai-era", "type": "conference", "authors_full": ["Ajmain Inqiad Alam", "Palash Ranjan Roy", "Farouq Al-Omari", "Chanchal K. Roy", "Banani Roy", "Kevin A. Schneider"], "venue_short": "ICSME 2025", "venue_full": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "publisher": "IEEE", "published_date": "2025-09-07", "first_page": "295", "last_page": "307", "abstract": "The increasing adoption of AI-generated code has reshaped modern software development, introducing syntactic and semantic variations in cloned code. Unlike traditional human-written clones, AI-generated clones exhibit systematic syntactic patterns and semantic differences learned from large-scale training data. This shift presents new challenges for classical code clone detection (CCD) tools, which have historically been validated primarily on human-authored codebases and optimized to detect syntactic (Type 1-3) and limited semantic clones. Given that AI-generated code can produce both syntactic and complex semantic clones, it is essential to evaluate the effectiveness of classical CCD tools within this new paradigm. In this paper, we systematically evaluate nine widely used CCD tools using GPTCloneBench, a benchmark containing GPT-3-generated clones. To contextualize and validate our results, we further test these detectors on established human-authored benchmarks, BigCloneBench and SemanticCloneBench, to measure differences in performance between traditional and AI-generated clones. Our analysis demonstrates that classical CCD tools, particularly those enhanced by effective normalization techniques, retain considerable effectiveness against AI-generated clones, while some exhibit notable performance variation compared to traditional benchmarks. This paper contributes by (1) evaluating classical CCD tools against AI-generated clones, providing critical insights into their current strengths and limitations; (2) highlighting the role of normalization techniques in improving detection accuracy; and (3) delivering detailed scalability and execution-time analyses to support practical CCD tool selection. The research underscores the continued relevance of classical CCD tools and suggests adopting a hybrid approach that combines both classical and AI-based methods to improve clone detection in the modern era.", "problem": "Classical code clone detection tools were validated mainly on human-written code, and it is unclear how well they detect clones in AI-generated code.", "relevant_to": ["evaluation of classical code clone detectors", "detection of AI-generated code clones", "semantic (Type-4) clone detection", "code normalization in clone detection", "clone detector scalability and execution time", "benchmarking with GPTCloneBench, BigCloneBench and SemanticCloneBench", "hybrid classical and AI-based clone detection"], "keywords": ["code clone detection", "AI-generated code", "GPT-3", "GPTCloneBench", "BigCloneBench", "SemanticCloneBench", "normalization", "empirical study"], "arxiv": "2509.25754", "code_url": "https://github.com/srlabUsask/classical-clone-detector-in-ai-era", "selected": true, "tags": ["Software Maintenance & Evolution", "Code Clones", "AI4SE", "Empirical SE"], "ml_topics": ["LLM-Generated Code", "Code Language Models"]}, {"title": "Towards Just-In-Time, Inclusive Clone Refactoring", "authors": "P. R. Roy", "venue": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME), Doctoral Symposium", "year": "2025", "pages": "pp. 884-886", "description": "Proposes a just-in-time approach to clone refactoring that is inclusive and automated, leveraging large language models and RAG techniques for trustworthy code maintenance.", "doi": "10.1109/ICSME64153.2025.00099", "bibtex": "@inproceedings{roy2025jit,\\n  title = {Towards Just-In-Time, Inclusive Clone Refactoring},\\n  url = {https://doi.org/10.1109/ICSME64153.2025.00099},\\n  doi = {10.1109/ICSME64153.2025.00099},\\n  booktitle = {2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)},\\n  publisher = {IEEE},\\n  author = {Roy, Palash},\\n  year = {2025},\\n  month = {Sept},\\n  pages = {884--886}\\n}", "slug": "jit-inclusive-clone-refactoring", "type": "doctoral_symposium", "authors_full": ["Palash Ranjan Roy"], "venue_short": "ICSME 2025 Doctoral Symposium", "venue_full": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "publisher": "IEEE", "published_date": "2025-09-07", "first_page": "884", "last_page": "886", "abstract": "Code clones are a well-known source of technical debt, often degrading software maintainability. Modern AI coding assistants can unintentionally introduce clones or even license-incompatible code, posing maintenance and legal challenges. This research proposes a Large Language Model (LLM)-powered clone refactoring assistant that proactively detects duplicative code during development and suggests high-level refactorings. By bridging traditional clone detection with LLM-driven code generation or transformation, the approach aims to remove redundancies early while ensuring changes remain behavior preserving and legally compliant. The assistant will integrate into development workflows to prevent clone propagation, flag potential intellectual property risks, and incorporate developer feedback for explainable, trustworthy operation. We will evaluate its impact on code quality and developer productivity, and assess how AI enhancements influence long-term maintenance efforts.", "problem": "Code clones add technical debt, and AI coding assistants can unintentionally introduce clones or license-incompatible code, creating maintenance and legal risks.", "relevant_to": ["just-in-time clone refactoring", "LLM-assisted refactoring", "clones introduced by AI coding assistants", "license compliance of generated code", "technical debt and software maintainability", "behavior-preserving code transformation", "developer-in-the-loop explainable tooling"], "keywords": ["code clones", "clone refactoring", "large language models", "AI coding assistants", "technical debt", "intellectual property", "software maintainability"], "track": "Doctoral Symposium", "tool_url": "https://github.com/srlabUsask/CLEAR", "tool_name": "CLEAR", "tags": ["Software Maintenance & Evolution", "Code Clones", "Refactoring"], "ml_topics": ["Large Language Models"]}, {"title": "An Exploratory Study on the Roles of LLMs in Code Similarity Detection and Generation", "authors": "P. R. Roy", "venue": "M.Sc. thesis, University of Saskatchewan", "year": "2025", "description": "M.Sc. thesis in Computer Science at the University of Saskatchewan, supervised by Kevin Schneider and Banani Roy. Three studies on large language models for code similarity: GPT-3 for semantic and cross-language clone generation, the quality of similar code from Stack Overflow, code search tools and LLMs, and Lang2Clone for cross-language clone detection.", "bibtex": "@mastersthesis{roy2025msc,\\n  author = {Roy, Palash Ranjan},\\n  title = {An Exploratory Study on the Roles of LLMs in Code Similarity Detection and Generation},\\n  school = {University of Saskatchewan},\\n  type = {M.Sc. thesis},\\n  year = {2025},\\n  url = {https://hdl.handle.net/10388/16429}\\n}", "slug": "msc-thesis-llms-code-similarity", "type": "thesis", "authors_full": ["Palash Ranjan Roy"], "venue_short": "M.Sc. Thesis, USask", "venue_full": "University of Saskatchewan", "publisher": "University of Saskatchewan", "published_date": "2025-01-13", "handle": "https://hdl.handle.net/10388/16429", "institution": "University of Saskatchewan", "dissertation_name": "M.Sc. thesis", "in_support_of": "M.Sc. in Computer Science", "abstract": "Code similarity, also referred to as cloned code, involves identifying redundant code fragments, enabling effective refactoring, and promoting code reuse. This, in turn, enhances both the maintainability and scalability of software systems. However, despite advancements in automated tools, detecting and generating clones, particularly across different programming languages and considering semantic variations—remains a significant challenge in software engineering.\\n\\nWith the rise of large language models (LLMs) such as GPT, Gemini, and LLaMA, there is growing interest in leveraging their capabilities to improve clone detection, code generation, and cross-language translation. Despite this interest, research has yet to thoroughly evaluate how these models can be systematically applied to address the challenges in these domains. This thesis aims to bridge that gap by investigating the role of LLMs in three studies: clone generation, code quality assessment of similar codes, and cross-language clone detection, with the goal of advancing software engineering practices.\\n\\nThe first study evaluates the performance of GPT-3 in generating semantic and cross-language code clones (similar codes) using the SemanticCloneBench dataset. Extensive experiments, validated by nine expert judges over 158 hours, show that GPT-3 achieved 62.14% accuracy and a 0.55 BLEU score in semantic clone generation, along with 91.25% accuracy in cross-language clone generation. These results underscore the potential of LLMs, particularly GPT-3, to support code reuse and facilitate migration across programming languages.\\n\\nThe second study assesses the quality of similar code generated through three approaches: human-generated solutions from Stack Overflow, LLM-based code search tools such as CodeBERT and GraphCodeBERT, and AI-powered models including GPT-4, Gemini Pro-1.5, and LLaMA-3-8B. Analyzing 800 programming questions (400 in Python and 400 in Java), the study demonstrates that GPT-4 consistently outperformed other tools in usability, accuracy, and overall code quality, while the code search tools underperformed. These findings offer valuable insights for developers, particularly in selecting reliable tools for high-quality code generation.\\n\\nIn the third study, I developed Lang2Clone, a novel tool that combines zero-shot prompting with GPT for code translation and NiCad for clone detection. Evaluations on the LeetCode and GPTCloneBench datasets showed that Lang2Clone achieved recall rates of 80% and 85%, respectively, with a precision of 95%. Notably, Lang2Clone outperformed state-of-the-art tools like GraphCodeBERT and CLCDSA in cross-language clone detection, particularly when translating between languages with similar programming paradigms.\\n\\nCollectively, these studies highlight the potential of LLMs to enhance key software engineering tasks, particularly in clone detection and code reuse. The findings also suggest promising avenues for future research, including the application of LLMs to broader challenges such as software maintenance and cross-language code translation, paving the way for more sophisticated and efficient development tools.", "problem": "Research had not yet thoroughly evaluated how large language models can be applied to clone generation, the quality of similar code, and cross-language clone detection.", "relevant_to": ["LLM-based code clone generation", "cross-language clone detection", "quality of LLM-generated code", "code similarity", "code search tools vs. LLMs"], "keywords": ["code clones", "large language models", "code similarity", "code generation", "code quality"], "tags": ["Program Comprehension", "Code Clones", "AI4SE"], "ml_topics": ["Large Language Models", "LLM-Generated Code"]}, {"title": "Are Large Language Models a Threat to Programming Platforms? An Exploratory Study", "authors": "M. M. Billah, P. R. Roy, Z. Codabux and B. Roy", "venue": "18th ACM/IEEE International Symposium on Empirical Software Engineering and Measurement (ESEM)", "year": "2024", "pages": "pp. 292-301", "description": "An exploratory study of how well large language models such as ChatGPT, Gemini and Meta AI solve problems on LeetCode, Codeforces and HackerRank, including live contests and certification tests, compared with human programmers.", "doi": "10.1145/3674805.3686689", "bibtex": "@inproceedings{billah2024llmthreat,\\n  series = {ESEM ''24},\\n  title = {Are Large Language Models a Threat to Programming Platforms? An Exploratory Study},\\n  url = {https://doi.org/10.1145/3674805.3686689},\\n  doi = {10.1145/3674805.3686689},\\n  booktitle = {Proceedings of the 18th ACM/IEEE International Symposium on Empirical Software Engineering and Measurement},\\n  publisher = {ACM},\\n  author = {Billah, Md Mustakim and Roy, Palash Ranjan and Codabux, Zadia and Roy, Banani},\\n  year = {2024},\\n  month = {Oct},\\n  pages = {292--301}\\n}", "slug": "llms-threat-programming-platforms", "type": "conference", "authors_full": ["Md Mustakim Billah", "Palash Ranjan Roy", "Zadia Codabux", "Banani Roy"], "venue_short": "ESEM 2024", "venue_full": "Proceedings of the 18th ACM/IEEE International Symposium on Empirical Software Engineering and Measurement", "publisher": "ACM", "published_date": "2024-10-24", "first_page": "292", "last_page": "301", "abstract": "Background: Competitive programming platforms such as LeetCode, Codeforces, and HackerRank provide challenges to evaluate programming skills. Technical recruiters frequently utilize these platforms as a criterion for screening resumes. With the recent advent of advanced Large Language Models (LLMs) like ChatGPT, Gemini, and Meta AI, there is a need to assess their problem-solving ability on the programming platforms. Aims: This study aims to assess LLMs’ capability to solve diverse programming challenges across programming platforms with varying difficulty levels, providing insights into their performance in real-time and offline scenarios, comparing them to human programmers, and identifying potential threats to established norms in programming platforms. Method: This study utilized 98 problems from LeetCode and 126 from Codeforces, covering 15 categories and varying difficulty levels. Then, we participated in nine online contests from Codeforces and LeetCode. Finally, two certification tests were attempted on HackerRank to gain insights into LLMs’ real-time performance. Prompts were used to guide LLMs in solving problems, and iterative feedback mechanisms were employed. We also tried to find any possible correlation among the LLMs in different scenarios. Results: LLMs generally achieved higher success rates on LeetCode (e.g., ChatGPT at 71.43%) but faced challenges on Codeforces. While excelling in HackerRank certifications, they struggled in virtual contests, especially on Codeforces. Despite diverse performance trends, ChatGPT consistently performed well across categories, yet all LLMs struggled with harder problems and lower acceptance rates. In LeetCode archive problems, LLMs generally outperformed users in time efficiency and memory usage but exhibited moderate performance in live contests, particularly in harder Codeforces contests compared to humans. Conclusions: While not necessarily a threat, the performance of LLMs on programming platforms is indeed a cause for concern. With the prospect of more efficient models emerging in the future, programming platforms need to address this issue promptly.", "problem": "Competitive programming platforms are used to assess programming skill and screen candidates, but it was unclear how well current large language models can solve their problems and whether this threatens the platforms'' norms.", "relevant_to": ["LLM performance on competitive programming", "LeetCode, Codeforces and HackerRank", "ChatGPT, Gemini and Meta AI code generation", "LLMs vs. human programmers", "academic and hiring integrity of programming assessments", "empirical evaluation of LLM problem solving by difficulty"], "keywords": ["large language models", "competitive programming", "programming platforms", "LeetCode", "Codeforces", "HackerRank", "ChatGPT", "empirical study"], "arxiv": "2409.05824", "code_url": "https://github.com/srlabUsask/LLM_Threat_Programming_Platforms", "artifact_url": "https://doi.org/10.5281/zenodo.11124223", "tags": ["AI4SE", "Empirical SE"], "ml_topics": ["LLM Evaluation", "Large Language Models"]}, {"title": "GPTCloneBench: A comprehensive benchmark of semantic clones and cross-language clones using GPT-3 model and SemanticCloneBench", "authors": "A. I. Alam, P. R. Roy, F. Al-Omari, C. K. Roy, B. Roy and K. A. Schneider", "venue": "2023 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "year": "2023", "pages": "pp. 1-13", "description": "Presents a benchmark for evaluating semantic code clones and cross-language clones generated using GPT-3.", "doi": "10.1109/ICSME58846.2023.00013", "preprint": "/papers/gptclonebench.pdf", "pdf": "/papers/gptclonebench.pdf", "bibtex": "@inproceedings{alam2023gptclonebench,\\n  title = {GPTCloneBench: A comprehensive benchmark of semantic clones and cross-language clones using GPT-3 model and SemanticCloneBench},\\n  url = {https://doi.org/10.1109/ICSME58846.2023.00013},\\n  doi = {10.1109/ICSME58846.2023.00013},\\n  booktitle = {2023 IEEE International Conference on Software Maintenance and Evolution (ICSME)},\\n  publisher = {IEEE},\\n  author = {Alam, Ajmain I. and Roy, Palash R. and Al-Omari, Farouq and Roy, Chanchal K. and Roy, Banani and Schneider, Kevin A.},\\n  year = {2023},\\n  month = {Oct},\\n  pages = {1--13}\\n}", "slug": "gptclonebench", "type": "conference", "authors_full": ["Ajmain Inqiad Alam", "Palash Ranjan Roy", "Farouq Al-Omari", "Chanchal K. Roy", "Banani Roy", "Kevin A. Schneider"], "venue_short": "ICSME 2023", "venue_full": "2023 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "publisher": "IEEE", "published_date": "2023-10-01", "first_page": "1", "last_page": "13", "abstract": "With the emergence of Machine Learning, there has been a surge in leveraging its capabilities for problem-solving across various domains. In the code clone realm, the identification of type-4 or semantic clones has emerged as a crucial yet challenging task. Researchers aim to utilize Machine Learning to tackle this challenge, often relying on the Big-CloneBench dataset. However, it’s worth noting that BigCloneBench, originally not designed for semantic clone detection, presents several limitations that hinder its suitability as a comprehensive training dataset for this specific purpose. Furthermore, CLCDSA dataset suffers from a lack of reusable examples aligning with real-world software systems, rendering it inadequate for cross-language clone detection approaches. In this work, we present a comprehensive semantic clone and cross-language clone benchmark, GPTCloneBench by exploiting SemanticCloneBench and OpenAI’s GPT-3 model. In particular, using code fragments from SemanticCloneBench as sample inputs along with appropriate prompt engineering for GPT-3 model, we generate semantic and cross-language clones for these specific fragments and then conduct a combination of extensive manual analysis, tool-assisted filtering, functionality testing and automated validation in building the benchmark. From 79,928 clone pairs of GPT-3 output, we created a benchmark with 37,149 true semantic clone pairs, 19,288 false semantic pairs(Type-1/Type-2), and 20,770 cross-language clones across four languages (Java, C, C#, and Python). Our benchmark is 15-fold larger than SemanticCloneBench, has more functional code examples for software systems and programming language support than CLCDSA, and overcomes BigCloneBench’s qualities, quantification, and language variety limitations. GPTCloneBench is available at https://doi.org/10.5281/zenodo.8259987.", "problem": "Existing clone benchmarks such as BigCloneBench and CLCDSA have limitations for training and evaluating semantic and cross-language clone detectors.", "relevant_to": ["code clone benchmarks", "semantic (Type-4) clone detection", "cross-language clone detection", "LLM-generated code clones", "GPT-3 for code generation", "training data for machine-learning clone detectors", "limitations of BigCloneBench and CLCDSA"], "keywords": ["GPTCloneBench", "code clone benchmark", "semantic clones", "cross-language clones", "GPT-3", "SemanticCloneBench", "BigCloneBench", "prompt engineering", "Java", "C", "C#", "Python"], "arxiv": "2308.13963", "code_url": "https://github.com/srlabUsask/GPTCloneBench", "dataset_url": "https://doi.org/10.5281/zenodo.8259987", "selected": true, "equal_contribution": ["Ajmain Inqiad Alam", "Palash Ranjan Roy"], "tags": ["Program Comprehension", "Code Clones", "AI4SE", "Benchmark"], "ml_topics": ["LLM-Generated Code", "Benchmarks & Datasets", "Prompting"]}, {"title": "Unveiling the Potential of Large Language Models in Generating Semantic and Cross-Language Clones", "authors": "P. R. Roy, A. I. Alam, F. Al-Omari, B. Roy, C. K. Roy and K. A. Schneider", "venue": "2023 IEEE 17th International Workshop on Software Clones (IWSC)", "year": "2023", "pages": "pp. 22-28", "description": "Explores how large language models can generate semantic code clones and cross-language clones, analyzing their potential applications and implications.", "doi": "10.1109/IWSC60764.2023.00011", "preprint": "/papers/unveling_potential.pdf", "pdf": "/papers/unveling_potential.pdf", "bibtex": "@inproceedings{roy2023unveiling,\\n  title = {Unveiling the Potential of Large Language Models in Generating Semantic and Cross-Language Clones},\\n  url = {https://doi.org/10.1109/IWSC60764.2023.00011},\\n  doi = {10.1109/IWSC60764.2023.00011},\\n  booktitle = {2023 IEEE 17th International Workshop on Software Clones (IWSC)},\\n  publisher = {IEEE},\\n  author = {Roy, Palash R. and Alam, Ajmain I. and Al-omari, Farouq and Roy, Banani and Roy, Chanchal K. and Schneider, Kevin A.},\\n  year = {2023},\\n  month = {Oct},\\n  pages = {22--28}\\n}", "slug": "llm-clone-generation-iwsc", "type": "workshop", "authors_full": ["Palash Ranjan Roy", "Ajmain Inqiad Alam", "Farouq Al-Omari", "Banani Roy", "Chanchal K. Roy", "Kevin A. Schneider"], "venue_short": "IWSC 2023", "venue_full": "2023 IEEE 17th International Workshop on Software Clones (IWSC)", "publisher": "IEEE", "published_date": "2023-10-01", "first_page": "22", "last_page": "28", "abstract": "Semantic and Cross-language code clone generation may be useful for code reuse, code comprehension, refactoring and benchmarking. OpenAI''s GPT model has potential in such clone generation as GPT is used for text generation. When developers copy/paste codes from Stack Overflow (SO) or within a system, there might be inconsistent changes leading to unexpected behaviours. Similarly, if someone possesses a code snippet in a particular programming language but seeks equivalent functionality in a different language, a semantic cross-language code clone generation approach could provide valuable assistance. In this study, using SemanticCloneBench as a vehicle, we evaluated how well the GPT-3 model could help generate semantic and cross-language clone variants for a given fragment. We have comprised a diverse set of code fragments and assessed GPT-3''s performance in generating code variants. Through extensive experimentation and analysis, where 9 judges spent 158 hours to validate, we investigate the model''s ability to produce accurate and semantically correct variants. Our findings shed light on GPT-3''s strengths in code generation, offering insights into the potential applications and challenges of using advanced language models in software development. Our quantitative analysis yields compelling results. In the realm of semantic clones, GPT-3 attains an impressive accuracy of 62.14% and 0.55 BLEU score, achieved through few-shot prompt engineering. Furthermore, the model shines in transcending linguistic confines, boasting an exceptional 91.25% accuracy in generating cross-language clones.", "problem": "It was unclear how well large language models such as GPT-3 can generate correct semantic and cross-language clone variants of a given code fragment.", "relevant_to": ["LLM-based code clone generation", "semantic clone generation", "cross-language clone generation", "GPT-3 for code generation", "few-shot prompt engineering for code", "human evaluation of generated code", "SemanticCloneBench"], "keywords": ["GPT-3", "large language models", "code clones", "semantic clones", "cross-language clones", "code generation", "SemanticCloneBench", "BLEU"], "arxiv": "2309.06424", "award": "People''s Choice Best Paper Award (IWSC 2023)", "equal_contribution": ["Ajmain Inqiad Alam", "Palash Ranjan Roy"], "tags": ["Program Comprehension", "Code Clones", "AI4SE"], "ml_topics": ["LLM-Generated Code", "Prompting (Few-Shot)"]}, {"title": "A Study on Paper and Author Ranking", "authors": "P. R. Roy, M. N. Islam, L. T. Jeba, M. A. Haq, I. A. Prome, M. Kaykobad and T. Kaykobad", "venue": "2022 International Conference on Innovations in Science, Engineering and Technology (ICISET)", "year": "2022", "pages": "pp. 545-549", "description": "Examines methodologies for ranking academic papers and authors, analyzing citation patterns and impact metrics in scientific literature.", "doi": "10.1109/ICISET54810.2022.9775821", "bibtex": "@inproceedings{roy2022ranking,\\n  title = {A Study on Paper and Author Ranking},\\n  url = {https://doi.org/10.1109/ICISET54810.2022.9775821},\\n  doi = {10.1109/ICISET54810.2022.9775821},\\n  booktitle = {2022 International Conference on Innovations in Science, Engineering and Technology (ICISET)},\\n  publisher = {IEEE},\\n  author = {Roy, Palash Ranjan and Islam, Md. Noushin and Jeba, Labiba Tasfiya and Haq, Md. Adnanul and Prome, Iffat Afsara and Kaykobad, Mohammad and Kaykobad, Tanvir},\\n  year = {2022},\\n  month = {Feb},\\n  pages = {545--549}\\n}", "slug": "paper-author-ranking", "type": "conference", "authors_full": ["Palash Ranjan Roy", "Md. Noushin Islam", "Labiba Tasfiya Jeba", "Md. Adnanul Haq", "Iffat Afsara Prome", "Mohammad Kaykobad", "Tanvir Kaykobad"], "venue_short": "ICISET 2022", "venue_full": "2022 International Conference on Innovations in Science, Engineering and Technology (ICISET)", "publisher": "IEEE", "published_date": "2022-02-26", "first_page": "545", "last_page": "549", "abstract": "As the number of journal issues, conferences and the overall scientific literature have been increasing at an exponential rate, it has become challenging for researchers to find appropriate and useful papers from the vast literature available to them. To solve this issue citation count, h-index, i10-index are used to rank authors. In 1998, Brin and Page introduced the algorithm PageRank which is also used in the scientific community for ranking research papers and authors. However, each of these metrics has its own drawbacks. We hypothesize that papers unveiling deeper truth are often not as well cited as those that are more challenging for a wider number of authors to assimilate and appreciate their works. So a simple count of the number of citations may fail to capture the essence of the quality of a paper. With a view to addressing this issue, we have introduced a new algorithm that also takes into account the quality of the researcher citing an article, and considers it in ranking. We have carried out experiments. While the experiments are not as comprehensive, results have been incorporated. They look promising in ranking authors and papers that are not cited too often due to difficulty in understanding them.", "problem": "Citation counts, h-index, i10-index and PageRank each have drawbacks for ranking papers and authors, and plain citation counts may undervalue papers that are hard to assimilate.", "relevant_to": ["paper ranking", "author ranking", "citation analysis", "PageRank for scholarly networks", "bibliometric indicators (h-index, i10-index)", "citation-quality-weighted ranking"], "keywords": ["paper ranking", "author ranking", "PageRank", "citation analysis", "h-index", "i10-index", "bibliometrics"], "tags": ["Scientometrics"]}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('highlights', '[{"title": "ACM SIGSOFT Distinguished Paper Award (2026)", "organization": "ACM International Conference on the Foundations of Software Engineering (FSE 2026)", "description": "Awarded to \\"Carbon-Taxed Transformers: A Green Compression Pipeline for Overgrown Language Models\\" (Proceedings of the ACM on Software Engineering, FSE 2026).", "year": "2026", "kind": "award"}, {"title": "Research Excellence in Science, Technology, Engineering, or Math (2025)", "organization": "Graduate Students'' Association, University of Saskatchewan", "description": "Graduate Students'' Association award for research in science, technology, engineering or math.", "link": "https://www.cs.usask.ca/news/2025/celebrating-excellence-computer-science-professor-and-graduate-students-receive-gsa-awards.php", "year": "2025", "kind": "award"}, {"title": "Best Thesis Award (M.Sc.) (2025)", "organization": "Department of Computer Science, University of Saskatchewan", "description": "Awarded for research during Master''s studies in Computer Science.", "year": "2025", "kind": "award"}, {"title": "SOAR Distinguished Research Award (2024)", "organization": "NSERC CREATE SOAR program, Canada", "description": "Research award from the NSERC Collaborative Research and Training Experience (CREATE) SOAR program.", "year": "2024", "kind": "award"}, {"title": "75th Anniversary Scholarship (2024)", "organization": "College of Graduate & Postdoctoral Studies (CGPS), University of Saskatchewan", "description": "Scholarship marking the 75th anniversary of the College of Graduate and Postdoctoral Studies.", "year": "2024", "kind": "award"}, {"title": "CS Citizenship Award (M.Sc.) (2024)", "organization": "Department of Computer Science, University of Saskatchewan", "description": "Recognized for citizenship and community contributions in the Department of Computer Science.", "link": "https://www.cs.usask.ca/news/2024/graduate-student-award-recipients.php", "year": "2024", "kind": "award"}, {"title": "ICSAC Research Award (2024)", "organization": "8th Symposium on Innovations in Computer Science and Applied Computing (ICSAC), University of Saskatchewan", "description": "Awarded for research presented at the ICSAC symposium.", "year": "2024", "kind": "award"}, {"title": "People''s Choice Best Paper Award (IWSC 2023)", "organization": "17th International Workshop on Software Clones (IWSC 2023), Bogotá, Colombia", "description": "Awarded by attendee vote to the IWSC 2023 paper on generating semantic and cross-language clones with large language models.", "link": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php", "year": "2023", "kind": "award", "paper_slug": "llm-clone-generation-iwsc"}, {"title": "Student Encouragement Award (IWSC 2023)", "organization": "17th International Workshop on Software Clones (IWSC 2023), Bogotá, Colombia", "description": "Awarded to Palash Ranjan Roy at IWSC 2023.", "link": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php", "year": "2023", "kind": "award"}, {"title": "People''s Choice Best Presentation Award (2023)", "organization": "SOAR Symposium at Saskatoon, Saskatchewan", "description": "Presentation voted best by attendees at the SOAR Symposium in Saskatoon.", "year": "2023", "kind": "award"}, {"title": "Award nominations (2024-2025)", "organization": "University of Saskatchewan and Western Association of Graduate Schools", "description": "Nominated for the University of Saskatchewan Best Thesis Award (2025), the WAGS Distinguished MSc Thesis Award in STEM (2025), the CS Geddes Award (M.Sc., 2024), the Carl McCrosky Innovation Scholarship (2024) and the Mark Kroeker Exceptional Student Leadership Award (2024).", "year": "2024-2025", "kind": "nomination"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('news', '[{"date": "2026-10-07", "icon": "", "title": "Two papers at ASE 2026: cross-domain clone detection via model merging, and the MergeSE tool", "description": "\\"A Unified Model for Cross-Domain Clone Detection via Model Merging\\" appeared in the research track and \\"MergeSE: Post-Hoc Model Merging for Software Engineering Tasks without Retraining\\" in the Tool Track of the IEEE/ACM International Conference on Automated Software Engineering.", "tag": "Paper", "pinned": true}, {"date": "2026-06-30", "icon": "", "title": "Carbon-Taxed Transformers published at FSE 2026 (paper and poster)", "description": "The full paper appeared in Proceedings of the ACM on Software Engineering (FSE 2026), and a companion poster appeared in the FSE 2026 poster track.", "tag": "Paper"}, {"date": "2026-02-11", "icon": "", "title": "Invited guest speaker, CARA Let''s Talk AI Club — Practical AI for Research Administration", "description": "A non-technical session for research administrators across Canada on where AI helps, its limits, and why human oversight must stay central.", "tag": "Talk"}, {"date": "2025-09-07", "icon": "", "title": "Two papers at ICSME 2025", "description": "\\"Are Classical Clone Detectors Good Enough for the AI Era?\\" in the research track and \\"Towards Just-In-Time, Inclusive Clone Refactoring\\" in the doctoral symposium of the IEEE International Conference on Software Maintenance and Evolution.", "tag": "Paper"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('media', '[{"outlet": "University of Saskatchewan, Computer Science", "date": "2025", "title": "Celebrating Excellence: Computer Science Professor and Graduate Students Receive GSA Awards", "url": "https://www.cs.usask.ca/news/2025/celebrating-excellence-computer-science-professor-and-graduate-students-receive-gsa-awards.php"}, {"outlet": "University of Saskatchewan, Computer Science", "date": "2024", "title": "Graduate Student Award Recipients", "url": "https://www.cs.usask.ca/news/2024/graduate-student-award-recipients.php"}, {"outlet": "USask News", "date": "2023", "title": "USask ‘clones’ researcher wins international award", "url": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('gallery', '[{"image": "/images/gsa_gala/gala-final-speech.jpg", "title": "Final Address as GSA President", "description": "Delivering my final address as President of the University of Saskatchewan Graduate Students'' Association at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy delivering his final address as GSA President at the 2026 University of Saskatchewan Graduate Students'' Association Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-awards-stage.jpg", "title": "Presenting the GSA Awards", "description": "Recognizing outstanding graduate students on stage during the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy presenting awards to graduate student recipients on stage at the 2026 University of Saskatchewan GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-cgps-dean-burshtyn.jpg", "title": "With CGPS Dean Dr. Deborah Burshtyn", "description": "With Dr. Deborah (Debby) Burshtyn, Dean of the College of Graduate and Postdoctoral Studies (CGPS), at the 2026 GSA Awards & Gala.", "altText": "Palash Roy with Dr. Deborah Burshtyn, Dean of the College of Graduate and Postdoctoral Studies, at the 2026 University of Saskatchewan GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-vice-provost-delbaere.jpg", "title": "With Vice-Provost Dr. Marjorie Delbaere", "description": "With Dr. Marjorie Delbaere, Interim Vice-Provost, Students and Learning, at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy with Dr. Marjorie Delbaere, Interim Vice-Provost Students and Learning, at the 2026 University of Saskatchewan GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-medicine-dean.jpg", "title": "With Medicine Dean Dr. Sarah Forgie", "description": "With Dr. Sarah Forgie, Dean of the College of Medicine, University of Saskatchewan, at the 2026 GSA Awards & Gala.", "altText": "Palash Roy with Dr. Sarah Forgie, Dean of the College of Medicine, at the 2026 University of Saskatchewan GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-provost-mcdougall.jpg", "title": "With Provost Dr. Patti McDougall", "description": "With Dr. Patti McDougall, Interim Provost and Vice-President Academic, at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy with Dr. Patti McDougall, Interim Provost and Vice-President Academic, at the 2026 University of Saskatchewan GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-executive-team.jpg", "title": "The GSA Executive Team", "description": "With the University of Saskatchewan GSA executive team at the 2026 Awards & Gala.", "altText": "Palash Roy with the University of Saskatchewan Graduate Students'' Association executive team at the 2026 GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/gsa_gala/gala-team-celebration.jpg", "title": "Celebrating with the Team", "description": "Celebrating a successful year with the GSA team at the 2026 Awards & Gala.", "altText": "Palash Ranjan Roy celebrating with the University of Saskatchewan GSA team at the 2026 GSA Awards and Gala", "featuresOwner": true, "date": "2026"}, {"image": "/images/Pic_section/Palash-Roy_Plaza de Bolívar.jpg", "title": "Plaza de Bolívar, Colombia", "description": "Exploring the historic heart of Bogotá at Plaza de Bolívar during my research visit for ICSME-2023.", "altText": "Palash Ranjan Roy at Plaza de Bolívar in Bogotá, Colombia, during his visit for ICSME 2023", "featuresOwner": true, "date": "2023"}, {"image": "/images/Pic_section/Palash-Justin_Santa Fe, Bogotá, Chocó.jpg", "title": "Santa Fe, Bogotá, Chocó", "description": "Making connections with fellow researchers in beautiful Colombia during our conference travel.", "altText": "Palash Ranjan Roy with Justin in Santa Fe, Bogotá, Colombia", "featuresOwner": true}, {"image": "/images/Pic_section/Palash_Group_Chico_Norte.jpg", "title": "Group Photo at Chico Norte", "description": "Exploring Chico Norte with friends from all over the world.", "altText": "Palash Ranjan Roy with international research colleagues at Chico Norte in Colombia", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Group_Parque_Nacional_Oriental.jpg", "title": "Parque Nacional Oriental", "description": "Taking a break from academic discussions to enjoy Colombia''s natural beauty at Parque Nacional Oriental.", "altText": "Palash Ranjan Roy with research colleagues at Parque Nacional Oriental in Colombia", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Cousins_Banff_Gondola.jpg", "title": "Banff Gondola with Cousins", "description": "Enjoying the breathtaking views of the Canadian Rockies with family at the Banff Gondola.", "altText": "Palash Ranjan Roy with his cousins at the Banff Gondola in the Canadian Rockies", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Cousins2_banff.jpg", "title": "Banff National Park", "description": "Another memorable moment with cousins exploring the natural wonders of Banff National Park.", "altText": "Palash Ranjan Roy and his cousins in Banff National Park, Alberta, Canada", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Family_Sulphur_Mountain.jpg", "title": "Family at Sulphur Mountain", "description": "A family adventure scaling the heights of Sulphur Mountain with its spectacular panoramic views.", "altText": "Palash Ranjan Roy with his family at Sulphur Mountain in Banff, Canada", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Mugdho(Cousin)_Montauk_Point_State_Park.jpg", "title": "Montauk Point State Park", "description": "An enjoyable day with my cousin Mugdho at Montauk Point State Park, taking in the coastal scenery.", "altText": "Palash Ranjan Roy and his cousin Mugdho at Montauk Point State Park in New York", "featuresOwner": true}, {"image": "/images/Pic_section/Palash-Roy_West_Village_NY(Friends_Building).jpg", "title": "West Village, New York", "description": "Couldn''t resist visiting the iconic ''Friends'' building during my trip to West Village, New York!", "altText": "Palash Ranjan Roy at the building from the TV show Friends in West Village, New York City", "featuresOwner": true}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
