INSERT INTO `content` (`section`,`data`) VALUES ('service', '[{"period": "2026-2027", "role": "Provost Search Committee Member", "description": "Committee member for the Provost and Vice-President Academic Search Committee.", "venue": "University of Saskatchewan", "category": "governance", "under": "gsa"}, {"period": "2025-2026", "role": "Senate Member", "description": "Served as a member of the University Senate, contributing to university-wide governance and academic policy.", "venue": "University of Saskatchewan", "category": "governance", "under": "gsa"}, {"period": "2025-2026", "role": "Award Committee Member", "description": "Served on multiple University of Saskatchewan award selection committees, including the Distinguished Researcher Award.", "venue": "University of Saskatchewan", "category": "governance", "under": "gsa"}, {"period": "2025-2026", "role": "CGPS Committee Member", "description": "Served on College of Graduate and Postdoctoral Studies (CGPS) committees, and presented graduate-student reports to University Council and college/faculty councils.", "venue": "University of Saskatchewan", "category": "governance", "under": "gsa"}, {"period": "2025-2026", "role": "Governance Committee Member", "description": "Served on a University Governance Committee as part of graduate student leadership.", "venue": "University of Saskatchewan", "category": "governance", "under": "gsa"}, {"period": "2022-Present", "role": "Peer Reviewer", "description": "Reviewed submissions for software engineering conferences and journals.", "venues": "ICSME, ASE, SCAM, SANER, MSR, JSS, TSE, and TOSEM", "category": "reviewing"}, {"period": "2023 – 2026", "role": "Research Supervisor, NSERC USRA students", "description": "Supervised 7 NSERC Undergraduate Student Research Award (USRA) students across the summers of 2023–2026; one student''s project won two undergraduate research awards (ICSAC 2024 and the SOAR Symposium 2024).", "venue": "Software Research Lab (SRLab) and iSE Lab, University of Saskatchewan", "category": "supervision"}, {"period": "Feb 2026", "date": "2026-02-11", "role": "Invited Talk (Guest Speaker)", "description": "Practical AI for Research Administration: Using AI Effectively, Responsibly, and with Human Oversight", "venue": "Canadian Association of Research Administrators (CARA) — Let''s Talk AI Club (online)", "category": "talk"}, {"period": "2025", "role": "Invited Talk", "description": "Large Language Models and Code Similarity", "venue": "Thompson Rivers University", "category": "talk"}, {"period": "2024", "role": "Invited Talk", "description": "AI for Software Engineering", "venue": "University of Saskatchewan", "category": "talk"}, {"period": "2024", "role": "Invited Talk", "description": "The Effects of Visual Embellishment on Comprehension and Memorability of Charts", "venue": "University of Saskatchewan", "category": "talk"}, {"period": "2023", "role": "Invited Talk", "description": "Software Engineering in Practice", "venue": "BRAC University", "category": "talk"}, {"period": "2022", "role": "Invited Talk", "description": "How to start building your first Robot?", "venue": "BRAC University", "category": "talk"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('references', '[{"name": "Rezwana Mahfuza Rimi", "title": "PhD Student, Dalhousie University", "image": "/images/rezwana.jpg", "text": "Palash was an integral part of my study environment when I first started university at Brac University. Palash spent time with me not just to assist me with day-to-day tasks, but also to encourage me with many academic endeavors over the years. He inspires his team, provides important input, and works for everyone to achieve better as a groupmate."}, {"name": "Farishta Kabir", "title": "Graduate Research and Teaching Assistant, University of Alberta", "image": "/images/farishta.jpg", "text": "I''ve had the pleasure of working with Palash during a few undergraduate courses and in the Robotics Club at BRAC University as a colleague. He always stood-out for his focused problem-solving approach and leadership in teamwork. Palash combines his expertise with an organizational mindset, making him a productive addition to any research project or team. Wishing him all the best for his future endeavours."}, {"name": "Fahmida Nipa", "title": "PS & CS Core Network, Cyber Security, Datacom", "image": "/images/Nipa.jpg", "text": "Throughout my Robotics Club journey, I have seen Palash to be very enthusiastic about robotics. Not to mention the leadership and managerial quality I got to experience while working with him was quite mentionable. I believe he will do his best wherever he set his foot, as his dignity towards his responsibilities resembles how much effort he can demonstrate. He is very adaptive and can communicate fluently with anyone when working in teams. I personally teamed up with him during several events organized by the club. those works were success and naturally outstanding as he pulled out the best from the team."}, {"name": "Syeda Umme Salma", "title": "Graduate Research Assistant, PhD Student", "image": "/images/omi.jpg", "text": "Palash is one of the greatest guys I''ve ever had as a collaborator, and we''ve worked together on multiple projects. I would strongly suggest his services to anyone in need of an software engineer. He is one of the wisest persons I have ever encountered, and his ability to solve any situation with a pleasant gesture is astonishing. Palash would be a valuable addition to any team."}, {"name": "Md. Noushin Islam Saad", "title": "Web Developer, Frontend Developer, MSc in Software Engineering", "image": "/images/saad.jpg", "text": "I was impressed by Palash''s ability to handle any situation calmly and patiently, even in the toughest situation. His natural skill has helped us succeed in many events throughout my journey at ROBU."}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
